from typing import List

def count_islands(grid: List[str]) -> int:
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    islands = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '#' and not visited[r][c]:
                islands += 1
                stack = [(r, c)]
                visited[r][c] = True

                while stack:
                    x, y = stack.pop()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '#' and not visited[nx][ny]:
                            visited[nx][ny] = True
                            stack.append((nx, ny))

    return islands

assert count_islands(['##.', '..#', '.#.']) == 3
assert count_islands(['...']) == 0
